1	export type Item = {
2	  type: string;
3	};
4	
5	export type QuoteStep = {
6	  op: "quote";
7	  items: Item[];
8	};
9	
10	export type Scenario = {
11	  customer: { yearsWithMHPCO: number };
12	  steps: QuoteStep[];
13	};
14	
15	export type ScenarioResult = {
16	  results: unknown[];
17	};
18	
19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	};
29	
30	const sum = (amounts: number[]): number =>
31	  amounts.reduce((total, amount) => total + amount, 0);
32	
33	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
34	
35	const quotePremium = (items: Item[]): number => {
36	  const basePremium = sum(items.map(basePremiumOf));
37	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
38	
39	  return Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
40	};
41	
42	export const runScenario = (scenario: Scenario): ScenarioResult => ({
43	  results: scenario.steps.map((step) => ({
44	    premium: quotePremium(step.items),
45	  })),
46	});
