const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const quotePremium = (items: Item[]): number => {
  const basePremium = sum(items.map(basePremiumOf));
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;

  return roundedInMHPCOsFavour(
    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};
